-- Shoulder Cam (ShoulderCam.lua, ShoulderCalibrate.lua, ProfileChoices.lua): public since 2026-11-15
L["The Shoulder Cam uses one of Blizzard's experimental camera settings. The game would warn about it every time you log in, so Cinematic keeps that warning away while the Shoulder Cam is on. If the camera ever acts up, turn the Shoulder Cam off and your own camera settings come back."] = "肩膀鏡頭使用了暴雪的一項實驗性鏡頭設定。遊戲每次登入都會對此發出警告，所以肩膀鏡頭開啟時 Cinematic 會擋住這則警告。如果鏡頭出了問題，關閉肩膀鏡頭，你自己的鏡頭設定就會恢復。"
L["Accept"] = "接受"
L["Shoulder Cam is paused while the gamepad UI is on: the game keeps your character centered in it."] = "遊戲控制器介面開啟時肩膀鏡頭會暫停：遊戲會讓你的角色保持在畫面中央。"
L["Swap shoulders (Shoulder Cam)"] = "切換肩膀（肩膀鏡頭）"
