L["Not supported at the moment"] = "暫不支援"
L["The Shoulder Cam doesn't work with the gamepad UI yet. While it's on, the game keeps your character in the middle of the screen, so the Shoulder Cam waits behind you and comes back by itself when you turn the gamepad UI off (Options > Gamepad (Beta) > Enable Gamepad UI)."] = "肩膀鏡頭暫不支援遊戲控制器介面。開啟時遊戲會讓你的角色保持在畫面中央，所以肩膀鏡頭會在你身後等待，關閉遊戲控制器介面後自動回來（選項 > 控制器（測試版）> 啟用控制器介面）。"
L["Calibrating my camera, please ignore this line for a moment: I'm measuring where my character sits on the screen as the camera moves over my shoulder. Thanks for your patience!"] = "我在校準鏡頭，請暫時忽略這句話：我在測量鏡頭移到肩膀上方時我的角色在畫面中的位置。謝謝耐心等候！"
