L["Calibrate the Shoulder Cam for %s?\n\nIt says a line in /say a few times (everyone near you sees it), so somewhere quiet is best. Stand still on open, flat ground and leave the camera alone for about 10 seconds."] = "為 %s 校準肩膀鏡頭？\n\n它會用 /說 說幾次一句話（附近的人都看得到），所以最好找個安靜的地方。站在開闊平坦的地面上不動，大約 10 秒內不要碰鏡頭。"
