L["How long the camera takes to move behind you when the Shoulder Cam pauses, and back."] = "肩膀鏡頭暫停時鏡頭移到你身後、以及再移回來所需的時間。"
L["The camera turns toward the NPC you talk to while their window is open."] = "與 NPC 對話時,在其視窗開啟期間鏡頭會轉向該 NPC。"
