L["Multi Quest fix"] = "多任務修正"
L["Dev test: at a quest giver with more quests, Accept clears your target first."] = "開發測試:在有更多任務的任務 NPC 處,接受任務會先清除你的目標。"
L["How long the camera takes to glide back over your shoulder after you close the window."] = "關閉視窗後,鏡頭滑回你肩膀上方所需的時間。"
L["Turns to your target everywhere, in fights too."] = "到處都轉向你的目標,戰鬥中也是。"
