L["How long the camera takes to glide back after you clear your target."] = "清除目標後鏡頭滑回所需的時間。"
L["Glide back when you clear your target"] = "清除目標時滑回"
L["Glides back instead of snapping when you clear your target, briefly using soft enemy targeting."] = "清除目標時滑回而非瞬間跳回,期間短暫使用軟性敵人選取。"
L["The ticked frames slide over to where you are on the screen."] = "勾選的框架會滑到你在畫面上的位置。"
L["Your cast bar and Personal Resource Display slide along as the camera turns to your target."] = "鏡頭轉向你的目標時,你的施法條和個人資源條會跟著滑動。"
