L["A bar in the top bar fills up over the minute Camp Benefits takes."] = "頂端列中的計量條會在「營地增益」所需的一分鐘內填滿。"
L["Shows this moment's card; with someone targeted, its buttons emote at them."] = "顯示此時刻的卡片;選取某人時,卡片上的按鈕會對他們做表情動作。"
L["Adds an emote button to this card, up to six."] = "在此卡片上加入表情動作按鈕,最多六個。"
L["When someone emotes at you, a small card lets you answer with one click."] = "有人對你做表情動作時,會出現一張小卡片讓你一鍵回應。"
L["Turns all Emote Vision cards on or off."] = "開啟或關閉所有 Emote Vision 卡片。"
L["Pick the moments that show a card and the emotes on it."] = "選擇要顯示卡片的時刻,以及卡片上的表情動作。"
L["These cards need the other player's nameplate. CineMode keeps friendly players' nameplates for them, hidden; outside it they show only while your friendly nameplates are on."] = "這些卡片需要對方玩家的名條。CineMode 會為它們保留友方玩家的名條並隱藏;在 CineMode 之外,只有在你的友方名條開啟時才會顯示。"
L["Turns these cards on or off."] = "開啟或關閉這些卡片。"
