L["Ignores the same person doing the same thing again for a few minutes."] = "幾分鐘內忽略同一個人再次做同一件事。"
L["How long a card stays; hovering holds it."] = "卡片停留的時間;滑鼠指向時會保持顯示。"
L["Gamepad answer button:"] = "控制器回應按鈕:"
L["In gamepad mode, press this to answer a card with the face buttons."] = "在控制器模式下,按此鍵即可用主按鈕回應卡片。"
L["Player menu"] = "玩家選單"
L["Menu:"] = "選單:"
L["Emotes on the right-click menu"] = "右鍵選單上的表情動作"
L["Adds an Emote section to the right-click menu on friendly players."] = "在友方玩家的右鍵選單中加入表情動作區塊。"
L["Pick its style, look and position."] = "選擇它的樣式、外觀與位置。"
