L["Shows a Stop camera button on screen while this camera runs."] = "此鏡頭執行時在畫面上顯示「停止鏡頭」按鈕。"
L["What stops the camera, plus its edge haze and Stop button."] = "什麼會停止鏡頭,以及其邊緣霧氣與停止按鈕。"
L["Turns this tab of the script on or off."] = "開啟或關閉腳本的此分頁。"
L["Not a script yet: it needs %s, which the runner doesn't have yet."] = "還不是腳本:它需要 %s,而執行器還沒有這項功能。"
L["Starts when: no trigger yet."] = "開始於:尚無觸發條件。"

