L["Cinematic is about bringing Azeroth to life: your screen changes with the moment you're in, hiding what you don't need and showing what you do."] = "Cinematic 的目的是讓艾澤拉斯活起來:你的畫面會隨當下的時刻變化,隱藏你不需要的,顯示你需要的。"
L["Reset Settings keeps what you made, Reset EVERYTHING deletes it all, and both reload the UI."] = "「重置設定」會保留你建立的東西,「全部重置」會刪除一切,兩者都會重新載入介面。"
