L["What takes you out of CineMode: fights, places, groups, moving and windows."] = "什麼會讓你離開 CineMode:戰鬥、地點、隊伍、移動與視窗。"
L["The minimap button, /cine hints, language and the menus' look."] = "小地圖按鈕、/cine 提示、語言,以及選單的外觀。"
L["How long things take to fade in out of combat."] = "非戰鬥中東西淡入所需的時間。"
L["How long things take to fade out."] = "東西淡出所需的時間。"
