L["Back after moving"] = "移動後恢復"
L["CineMode comes back once you've kept moving this long."] = "你持續移動這麼久之後,CineMode 會恢復。"
L["Allow outside CineMode"] = "在 CineMode 之外也允許"
L["CineMode hides your buffs and debuffs: pick what brings them back."] = "CineMode 會隱藏你的增益與減益:選擇什麼會讓它們回來。"
