L["Override Default Buff Reveal Time"] = "覆寫預設增益顯示時間"
L["How long a new buff keeps the buffs up."] = "新增益讓增益保持顯示多久。"
L["Override Default Debuff Reveal Time"] = "覆寫預設減益顯示時間"
L["How long a new debuff keeps the buffs up."] = "新減益讓增益保持顯示多久。"
L["Gaining this doesn't bring your buffs up; type a spell ID or name."] = "獲得此增益不會讓你的增益出現;請輸入法術 ID 或名稱。"
