L["How far the camera may sway to either side."] = "鏡頭向兩側搖擺的最大幅度。"
L["Each move also tilts the camera to a random angle between these limits."] = "每次移動時鏡頭也會仰俯到這些限制之間的隨機角度。"
L["The camera never tilts more than this far below where it started."] = "鏡頭向下仰俯永遠不會超過起始位置以下這麼多。"
L["How much of each move is spent speeding up and slowing down."] = "每次移動中有多少時間用於加速與減速。"
L["How long the camera rests between sweeps."] = "鏡頭在兩次掃視之間停留多久。"
L["Puts this camera's settings back to your profile's values."] = "將此鏡頭的設定還原為你設定檔的值。"
L["Runs this camera for 30 seconds where you stand."] = "在你站立的地方執行此鏡頭 30 秒。"
