L["Doing the emote or pressing the sit key."] = "做出該表情動作或按下坐下鍵。"
L["Clicking Sit, Kneel or Lie down on the campfire card, or its fire button (Emote Vision)."] = "點擊營火卡片上的「坐下」、「跪下」或「躺下」,或其火焰按鈕(Emote Vision)。"
