L["Casting a teleport spell."] = "施放傳送法術。"
L["Logging out where the game counts down first."] = "在遊戲會先倒數的地方登出。"
L["Doing the emote while standing still."] = "站著不動時做出該表情動作。"
L["Casting Fishing, until you move or jump."] = "施放釣魚,直到你移動或跳躍。"
L["Being flagged AFK."] = "被標記為暫離。"
L["Standing still for the time below with nothing else going on."] = "沒有其他事情時站著不動下方設定的時間。"
L["Taking off on a flight path."] = "從飛行路線起飛。"
L["Talking to a quest giver."] = "與任務 NPC 對話。"
L["Talking to an NPC about a quest step."] = "與 NPC 談論任務步驟。"
L["On flight paths, the camera sways side to side with an occasional fly-by."] = "在飛行路線上,鏡頭會左右搖擺,偶爾來個掠過鏡頭。"
L["Your target's frames fade until you pick a new target or land."] = "你目標的框架會淡出,直到你選取新目標或降落。"
L["Sway from side to side"] = "左右搖擺"
L["The camera sways from side to side around where it started."] = "鏡頭在起始位置附近左右搖擺。"
L["Your character does /look as a fly-by starts, which players nearby see."] = "掠過鏡頭開始時你的角色會做 /look,附近的玩家看得到。"
L["About one fly-by per this many seconds of flight."] = "大約每飛行這麼多秒出現一次掠過鏡頭。"
L["Turn round"] = "轉身"
L["Turn back before landing"] = "降落前轉回"
L["Before you land, the camera turns back to where it was at takeoff."] = "降落前鏡頭會轉回起飛時的位置。"
L["Turned back by"] = "轉回完成於"
