L["When you stand still a while or go AFK, the camera slowly circles your character."] = "你站著不動一段時間或暫離時,鏡頭會緩緩環繞你的角色。"
L["The camera sweeps around your character, pausing between sweeps."] = "鏡頭會繞著你的角色掃視,每次掃視之間停頓。"
L["While you auto-run, the camera follows along until you stop or steer."] = "你自動奔跑時,鏡頭會跟著你,直到你停下或轉向。"
L["The camera eases out a little, then drifts in and out."] = "鏡頭稍微拉遠,然後前後飄移。"
L["When you rest, sit or dance, the camera slowly turns to face you and eases in."] = "你休息、坐下或跳舞時,鏡頭會緩緩轉向面對你並拉近。"
L["How far the camera comes down toward the ground as it turns."] = "鏡頭轉動時向地面降低多少。"
L["The camera eases in close, then drifts a little in and out."] = "鏡頭拉近,然後稍微前後飄移。"
L["The close-up distance the cozy camera zooms in to."] = "悠閒鏡頭拉近到的特寫距離。"
L["How much lower the camera sways, to look out across the view."] = "鏡頭搖擺時降低多少,以眺望景色。"
L["The camera eases out a little, then drifts slowly in and out."] = "鏡頭稍微拉遠,然後緩緩前後飄移。"
L["The camera sways a little from side to side."] = "鏡頭稍微左右搖擺。"
L["How much lower the camera sways, to look out across the water."] = "鏡頭搖擺時降低多少,以眺望水面。"
L["When you die, the camera slowly circles your body until you release or are revived."] = "你死亡時,鏡頭會緩緩環繞你的屍體,直到你釋放靈魂或被復活。"
L["If you die in a boss fight, the death camera waits for it to end."] = "如果你在首領戰中死亡,死亡鏡頭會等到戰鬥結束。"
L["No death camera when you can come back yourself, like with a soulstone."] = "當你能自行復活時(例如有靈魂石)不使用死亡鏡頭。"
L["Adds a button under the release popup to get your own view back."] = "在釋放靈魂的彈出視窗下方加入一個按鈕,讓你取回自己的視角。"
L["How far the camera pulls back while you're dead."] = "你死亡時鏡頭拉遠多少。"
L["How far the camera rises to look down on your body."] = "鏡頭升高多少以俯視你的屍體。"
L["The groups ticked here stay up while the death camera hides your frames."] = "死亡鏡頭隱藏你的框架時,這裡勾選的群組會保持顯示。"
L["Music file IDs, separated by commas; one plays at random when you die."] = "音樂檔案 ID,以逗號分隔;你死亡時會隨機播放其中一首。"
L["The camera turns toward NPCs as they talk near you."] = "NPC 在你附近說話時,鏡頭會轉向他們。"
L["The fastest the camera swings toward a new speaker."] = "鏡頭轉向新說話者的最快速度。"
L["How far from the screen's center the speaker ends up."] = "說話者最後距離畫面中央多遠。"
L["How far the camera drifts side to side once settled."] = "穩定後鏡頭左右飄移的幅度。"
L["The camera turns around to find speakers you can't see."] = "鏡頭會轉身尋找你看不到的說話者。"
L["Snaps to speakers, adds a tall letterbox with subtitles and fades the whole UI."] = "立即對準說話者,加上有字幕的高黑邊,並淡出整個介面。"
L["How fast the camera zooms back out once the talking is over."] = "對話結束後鏡頭拉遠的速度。"
L["The longest a zoom in or out can take."] = "一次拉近或拉遠最多可花的時間。"
L["How long no one must talk before the camera turns back."] = "多久沒有人說話,鏡頭才會轉回。"
L["When you talk to a quest giver, the camera zooms in and looks past you at them."] = "你與任務 NPC 對話時,鏡頭會拉近並越過你看向他們。"
L["Also zooms in for NPCs with nothing to say about quests."] = "對於沒有任務相關內容可說的 NPC 也會拉近。"
L["The camera stays put when a quest giver only has dailies or weeklies."] = "任務 NPC 只有每日或每週任務時,鏡頭保持不動。"
L["How far the camera turns to one side to look past you."] = "鏡頭轉向一側越過你看的幅度。"
L["How long the turn to the side takes."] = "轉向一側所需的時間。"
L["How fast the camera zooms back out once you walk away."] = "你走開後鏡頭拉遠的速度。"
L["How far the camera comes down toward eye level."] = "鏡頭向下降到視線高度的程度。"
L["When you cast your Hearthstone or a teleport, the camera spins around you as it zooms in."] = "你施放爐石或傳送時,鏡頭會繞著你旋轉並拉近。"
