L["Top turn speed"] = "最高轉向速度"
L["The fastest you can turn."] = "你能轉向的最快速度。"
L["Ease back over"] = "緩和恢復經過"
L["How long your own Mouse Look Speed takes to come back after you slow down."] = "你放慢後,你自己的滑鼠視角速度需要多久恢復。"
L["Ramp up right-click turn speed"] = "逐步提高右鍵轉向速度"
L["Each right-click turn starts slow and builds up to your own speed."] = "每次右鍵轉向都會從慢開始,逐漸提高到你自己的速度。"
L["Start at"] = "起始於"
L["%d%% of your speed"] = "你速度的 %d%%"
L["How fast a turn starts, as a share of your own Mouse Look Speed."] = "轉向開始時的速度,以你自己滑鼠視角速度的比例表示。"
L["Up to full speed over"] = "提高到全速經過"
L["How long a turn takes to build up to full speed."] = "轉向提高到全速所需的時間。"
L["Slow looking up and down too"] = "上下看也放慢"
L["Looking up and down slows by the same share as turning."] = "上下看時會以與轉向相同的比例放慢。"
L["Turns the whole Atmosphere hub on or off at once."] = "一次開啟或關閉整個氛圍分類。"
L["How the game world looks in CineMode: vignette, inn glow, weather and depth of field."] = "CineMode 中遊戲世界的外觀:暗角、旅店光暈、天氣與景深。"
L["Pick where and when each effect shows in CineMode."] = "選擇每種效果在 CineMode 中何時何地顯示。"
L["Shows all the time in CineMode, fights included."] = "在 CineMode 中一直顯示,包括戰鬥中。"
L["Rain, snow and sandstorms tint the scene, more strongly in heavier weather."] = "雨、雪和沙塵暴會為場景染色,天氣越惡劣越明顯。"
L["Reduce view distance in bad weather"] = "惡劣天氣時縮短視野距離"
L["Brings the view distance in during rain, snow or sandstorms, more the heavier it gets."] = "下雨、下雪或沙塵暴時縮短視野距離,天氣越惡劣縮得越多。"
L["The game's graphics settings one by one, shared by every profile on this computer."] = "逐項列出遊戲的顯示設定,由此電腦上所有設定檔共用。"
L["Uses the settings below, or the game's own when turned off."] = "使用下方的設定,關閉時則使用遊戲本身的設定。"
L["World"] = "世界"
L["Ground clutter, view distance, detail and shadows."] = "地面雜物、視野距離、細節與陰影。"
L["Sky and water"] = "天空與水"
L["Clouds, fog, reflections and ripples."] = "雲、霧、反射與漣漪。"
L["Effects"] = "效果"
L["Particles, glow, blood and sharpening."] = "粒子、光暈、血液與銳利化。"
L["HDR"] = "HDR"
L["HDR output and brightness."] = "HDR 輸出與亮度。"
L["Nameplate distance and zoom distance."] = "名條距離與縮放距離。"
L["How far away grass and flowers start thinning out."] = "草和花從多遠開始變稀疏。"
L["How far the land is drawn in full; very demanding on frame rate."] = "地形以完整細節繪製的距離;非常吃幀數。"
L["How far away trees, rocks and other objects keep their full detail."] = "樹木、岩石等物件保持完整細節的距離。"
L["How far away small objects stay before they fade out."] = "小型物件在多遠之前保持顯示,之後淡出。"
L["How far away creatures and characters keep their full detail."] = "生物與角色保持完整細節的距離。"
L["How far away nameplates show, in yards."] = "名條顯示的距離,以碼為單位。"
L["How far out you can zoom the camera."] = "你能將鏡頭拉遠多少。"
L["Higher gives sharper shadow edges, lower saves frame rate."] = "越高陰影邊緣越銳利,越低越節省幀數。"
L["Horizon distance"] = "地平線距離"
L["How far the flat horizon past the land reaches."] = "地形外平坦地平線延伸的距離。"
L["Sky detail"] = "天空細節"
L["How detailed the clouds and sky are."] = "雲與天空的細緻程度。"
L["Volumetric fog"] = "體積霧"
L["Fog with depth in place of the usual distance fog."] = "以有深度的霧取代一般的遠景霧。"
L["Water reflections"] = "水面反射"
L["How much of the world water reflects."] = "水面反射世界的程度。"
L["Water ripples"] = "水面漣漪"
L["How detailed the ripples on water are."] = "水面漣漪的細緻程度。"
L["Particle density"] = "粒子密度"
L["How many particles spells and effects show."] = "法術與效果顯示的粒子數量。"
L["Full-screen glow"] = "全螢幕光暈"
L["A soft glow around bright light."] = "明亮光線周圍的柔和光暈。"
L["Gray screen on death"] = "死亡時灰色畫面"
L["The world turns gray while you're dead."] = "你死亡時世界會變成灰色。"
L["Blood and gore"] = "血液與血腥"
L["How much blood shows in fights, from none to the most."] = "戰鬥中顯示多少血液,從無到最多。"
L["Always sharpen"] = "一律銳利化"
L["Sharpens the picture even at full render scale."] = "即使在完整渲染比例下也會銳利化畫面。"
L["HDR output"] = "HDR 輸出"
L["Sends HDR to your monitor; Windows HDR must be on and Auto HDR off."] = "將 HDR 傳送到你的螢幕;必須開啟 Windows HDR 並關閉自動 HDR。"
L["Use peak brightness"] = "使用峰值亮度"
L["Peak brightness"] = "峰值亮度"
L["Your monitor's peak brightness, in nits."] = "你螢幕的峰值亮度,以尼特為單位。"
L["HDR strength"] = "HDR 強度"
L["How strong HDR is; works with peak brightness only."] = "HDR 的強度;只在使用峰值亮度時有效。"
L["Use reference brightness"] = "使用參考亮度"
L["Reference brightness"] = "參考亮度"
L["How bright white looks in HDR, in nits."] = "白色在 HDR 中看起來的亮度,以尼特為單位。"
L["Sky and weather"] = "天空與天氣"
L["Water"] = "水"
L["Restart graphics"] = "重新啟動顯示"
L["Restarts the game's graphics without leaving the game; the screen goes black for a moment."] = "不離開遊戲即重新啟動遊戲的顯示;畫面會短暫變黑。"
L["Sound and music during CineMode; your own sound settings come back afterward."] = "CineMode 期間的音效與音樂;之後會恢復你自己的音效設定。"
L["Plays music when a camera starts in CineMode and fades it out when the UI returns."] = "CineMode 中鏡頭啟動時播放音樂,介面回來時淡出。"
L["Pick where and when music can play in CineMode."] = "選擇 CineMode 中音樂可以在何時何地播放。"
L["After a camera starts music, no camera starts it again for this long."] = "一個鏡頭開始播放音樂後,這段時間內不會再有鏡頭開始播放。"
L["Fades music out once you leave the camera modes and move on."] = "你離開鏡頭模式並繼續前進時,音樂會淡出。"
L["Each row is a scene that plays its camera when one of its triggers happens."] = "每一列都是一個場景,在其觸發條件之一發生時播放其鏡頭。"
L["Lets the scenes below play their cameras when their triggers happen."] = "讓下方的場景在其觸發條件發生時播放其鏡頭。"
L["Auto-running in walk mode."] = "以行走模式自動奔跑。"
L["Auto-running."] = "自動奔跑。"
L["Dying, until you release or are resurrected."] = "死亡,直到你釋放靈魂或被復活。"
L["An NPC talking to you or your party; the camera swings toward whoever's talking."] = "NPC 正在對你或你的隊伍說話;鏡頭會轉向說話的人。"
L["Other NPCs talking near you, once you've stood still a while."] = "你站著不動一段時間後,附近有其他 NPC 在說話。"
L["Starts music as this camera starts; needs the Audio page on."] = "此鏡頭啟動時開始播放音樂;需要開啟音效頁面。"
L["Plays a song of its own while the death camera runs."] = "死亡鏡頭執行時播放專屬的歌曲。"
L["Brings CineMode on while this camera runs, when Start in CineMode is off."] = "若「以 CineMode 啟動」已關閉,在此鏡頭執行時開啟 CineMode。"
L["Buff names or spell IDs, separated by commas."] = "增益名稱或法術 ID,以逗號分隔。"
L["Words in an object's name that mark it as a seat, separated by commas."] = "物件名稱中標示其為座位的字詞,以逗號分隔。"
L["How long you stand still before this row's camera starts."] = "你站著不動多久後,此列的鏡頭才會啟動。"
L["How long the camera waits on a quest window before it starts."] = "鏡頭在任務視窗上等待多久才啟動。"
L["How long the camera waits on the window before it starts."] = "鏡頭在視窗上等待多久才啟動。"
L["How long you stand still before NPCs chatting nearby start this camera."] = "你站著不動多久後,附近 NPC 的閒聊才會啟動此鏡頭。"
L["How long you keep going before this row's camera starts."] = "你持續多久後,此列的鏡頭才會啟動。"
L["Whether this row's camera may start in or after a fight."] = "此列的鏡頭是否可在戰鬥中或戰鬥後啟動。"
L["Where this row's camera may start."] = "此列的鏡頭可在哪裡啟動。"
L["Pause cameras while a window is open"] = "視窗開啟時暫停鏡頭"
L["Scenes pause while a window like the map or spellbook is open."] = "地圖或法術書等視窗開啟時,場景會暫停。"
L["Lists the rows by camera name or by scene name."] = "依鏡頭名稱或場景名稱列出各列。"
L["Make a scene of your own with its triggers, camera and end."] = "用你自己的觸發條件、鏡頭與結束方式製作場景。"
L["A scene of your own; open it to set its triggers and when it ends."] = "你自己的場景;開啟它以設定其觸發條件與結束時機。"
L["Copies this row just below, so you can give it another camera."] = "將此列複製到正下方,讓你可以給它另一個鏡頭。"
L["Deletes this scene so it starts no camera."] = "刪除此場景,使它不再啟動任何鏡頭。"
L["Your own name for this row, shown on the grid."] = "你自己為此列取的名稱,顯示在表格中。"
L["The camera this row starts."] = "此列啟動的鏡頭。"
L["This row's camera may start anywhere."] = "此列的鏡頭可在任何地方啟動。"
L["Indoors, the camera modes zoom out and swing less so they don't hit walls."] = "在室內,鏡頭模式會減少拉遠與擺動,以免撞到牆壁。"
L["How far past your own distance the slow zoom may pull back indoors."] = "在室內,緩慢縮放最多可比你自己的距離再拉遠多少。"
L["Stops the AFK camera sweeping around you indoors, where it can hit walls."] = "在室內停止暫離鏡頭繞著你掃視,因為那裡可能會撞到牆壁。"
