L["Shows it the whole time, CineMode or not."] = "一直顯示,無論是否在 CineMode 中。"
L["CineMode hides everything: pick which frames show, and when."] = "CineMode 會隱藏一切:選擇哪些框架顯示,以及何時顯示。"
L["CineMode hides everything: tick which frames show, and when."] = "CineMode 會隱藏一切:勾選哪些框架顯示,以及何時顯示。"
L["CineMode hides these frames, and shows them only when their rows say."] = "CineMode 會隱藏這些框架,只在其列設定時才顯示。"
L["CineMode hides the frames in this section, and shows them only when their rows say."] = "CineMode 會隱藏此區塊中的框架,只在其列設定時才顯示。"
L["Not in use"] = "未使用"
L["Shows or hides its parts."] = "顯示或隱藏其部分。"
L["Shows the same parts as the Target rows."] = "顯示與「目標」列相同的部分。"
