L["Same as"] = "與此相同"
L["raid frames"] = "團隊框架"
L["Opens the Raid tab."] = "開啟團隊分頁。"
L["Your Edit Mode layout has Use Raid-Style Party Frames ticked."] = "你的編輯模式版面配置已勾選「使用團隊風格的隊伍框架」。"
L["Your Edit Mode layout has Use Raid-Style Party Frames unticked."] = "你的編輯模式版面配置未勾選「使用團隊風格的隊伍框架」。"
L["Hide keybinds"] = "隱藏按鍵名稱"
L["Hides the key names on the action bar buttons (1, a-Q, s-2...), CineMode or not."] = "隱藏快捷鍵按鈕上的按鍵名稱(1、a-Q、s-2...),無論是否在 CineMode 中。"
L["Hide macro names"] = "隱藏巨集名稱"
L["Hides the macro names on the action bar buttons, CineMode or not."] = "隱藏快捷鍵按鈕上的巨集名稱,無論是否在 CineMode 中。"
L["Show while the spellbook is open"] = "法術書開啟時顯示"
L["Keeps your action bars up while the spellbook or macros window is open."] = "法術書或巨集視窗開啟時,讓你的快捷列保持顯示。"
L["PRD"] = "個人資源條"
L["Timers"] = "計時器"
L["Highlight"] = "高亮"
L["CineMode hides the unit frames: pick which show, and when."] = "CineMode 會隱藏單位框架:選擇哪些顯示,以及何時顯示。"
L["CineMode hides your personal resource display: pick which parts show, and when."] = "CineMode 會隱藏你的個人資源條:選擇哪些部分顯示,以及何時顯示。"
L["CineMode hides your cast bar: pick when it shows."] = "CineMode 會隱藏你的施法條:選擇何時顯示。"
L["CineMode hides the action bars: pick which show, and when."] = "CineMode 會隱藏快捷列:選擇哪些顯示,以及何時顯示。"
L["CineMode hides your buffs and debuffs: pick when they show."] = "CineMode 會隱藏你的增益與減益:選擇何時顯示。"
L["CineMode hides timers and meters: pick which show, and when."] = "CineMode 會隱藏計時器與統計:選擇哪些顯示,以及何時顯示。"
L["CineMode hides the Cooldown Manager: pick which bars show, and when."] = "CineMode 會隱藏冷卻管理器:選擇哪些條顯示,以及何時顯示。"
L["CineMode hides your swing timer: pick when it shows."] = "CineMode 會隱藏你的揮擊計時器:選擇何時顯示。"
L["CineMode hides the chat window: pick when it shows."] = "CineMode 會隱藏聊天視窗:選擇何時顯示。"
L["CineMode hides info frames and menus: pick which show, and when."] = "CineMode 會隱藏資訊框架與選單:選擇哪些顯示,以及何時顯示。"
L["CineMode hides the minimap: pick which parts show, and when."] = "CineMode 會隱藏小地圖:選擇哪些部分顯示,以及何時顯示。"
L["CineMode hides the quest tracker: pick when it shows."] = "CineMode 會隱藏任務追蹤:選擇何時顯示。"
L["CineMode hides the party frames: pick when they show."] = "CineMode 會隱藏隊伍框架:選擇何時顯示。"
L["CineMode hides the raid frames: pick when they show."] = "CineMode 會隱藏團隊框架:選擇何時顯示。"
L["CineMode hides the raid-style party frames: pick when they show."] = "CineMode 會隱藏團隊樣式的隊伍框架:選擇何時顯示。"
L["CineMode hides your character's highlight: pick when it shows."] = "CineMode 會隱藏你角色的高亮:選擇何時顯示。"
L["CineMode hides these frames: pick which show, and when."] = "CineMode 會隱藏這些框架:選擇哪些顯示,以及何時顯示。"
L["Pick where chat bubbles show."] = "選擇對話泡泡在哪裡顯示。"
L["Pick where and when each kind of bubble shows."] = "選擇每種對話泡泡在何時何地顯示。"
L["These bubbles show everywhere, in fights and out."] = "這些對話泡泡到處都顯示,戰鬥中與非戰鬥中皆然。"
L["Cinematic draws its own bubbles for speech whose game bubble you can't see."] = "看不到遊戲對話泡泡的說話內容,Cinematic 會自己繪製對話泡泡。"
L["Shows speech from someone off screen in a bubble low on the screen."] = "以畫面下方的對話泡泡顯示畫面外某人的說話內容。"
L["Opens the Chat Bubble Style page: how off-screen bubbles look and where they show."] = "開啟對話泡泡樣式頁面:畫面外對話泡泡的外觀與顯示位置。"
L["Shows emotes in the off-screen bubbles too, instead of in chat."] = "在畫面外的對話泡泡中也顯示表情動作,而非在聊天中。"
L["Moves bubbles at the very top of the screen down where you can read them."] = "將位於畫面最頂端的對話泡泡下移到你看得到的地方。"
L["Small helpers for getting around the world."] = "在世界中遊歷時的小幫手。"
L["Turns all the Quality of Life helpers on or off."] = "開啟或關閉所有生活便利小幫手。"
L["Opens the character window when you drag gear out of your bags."] = "從背包拖出裝備時開啟角色視窗。"
L["Adds a button to view the talents of someone you inspect."] = "加入一個按鈕,可查看你觀察對象的天賦。"
L["Adds a talent calculator button to your talents window to plan a build."] = "在你的天賦視窗中加入天賦模擬器按鈕,以規劃配點。"
L["Moves game windows away from the left edge so your character stays in view."] = "將遊戲視窗移離左側邊緣,讓你的角色保持在畫面中。"
L["Lets you drag the game's windows to move them."] = "讓你可以拖曳遊戲的視窗來移動它們。"
L["Adds an icon to chat windows to copy their text."] = "在聊天視窗加入一個圖示,可複製其文字。"
L["Keep chat history"] = "保留聊天記錄"
L["Chat windows bring back their last lines after a reload or login."] = "聊天視窗在重新載入或登入後會帶回最後幾行。"
L["Show the time on those lines"] = "在那些行上顯示時間"
L["Puts the time at the start of brought-back lines."] = "在帶回的行開頭加上時間。"
L["Show XP left to level"] = "顯示升級所需經驗值"
L["Shows how much XP you still need for the next level."] = "顯示你升到下一級還需要多少經驗值。"
L["The camera zooms to the distance below when you log in or reload."] = "登入或重新載入時,鏡頭會縮放到下方的距離。"
L["The camera distance to start at."] = "起始的鏡頭距離。"
L["A button at the top of the screen that reloads the UI in one click."] = "畫面頂端的按鈕,一鍵重新載入介面。"
L["Reopens the windows you had open after a reload."] = "重新載入後重新開啟你原本開著的視窗。"
L["Hides floating damage and healing numbers in CineMode out of combat."] = "在 CineMode 中非戰鬥時隱藏浮動的傷害與治療數字。"
L["Hides the red error text while you're fighting."] = "戰鬥中隱藏紅色錯誤文字。"
L["Hides the red error text while you're out of combat."] = "非戰鬥中隱藏紅色錯誤文字。"
L["Turns the Hunter helpers on or off."] = "開啟或關閉獵人小幫手。"
L["Right-clicking an enemy uses Auto Shot when it's far enough away."] = "敵人距離夠遠時,右鍵點擊會使用自動射擊。"
L["Moves the smallest ammo stack first after Clean Up Bags, so it's shot first."] = "整理背包後先移動最小的彈藥堆,讓它先被射出。"
L["Adds a Fill button at vendors that fills your quiver with ammo."] = "在商人處加入「填滿」按鈕,用彈藥填滿你的箭袋。"
L["Keeps your pet frame up while your pet isn't happy."] = "你的寵物不快樂時,讓寵物框架保持顯示。"
L["The pet frame fades with the UI while a camera mode runs."] = "鏡頭模式執行時,寵物框架會隨介面淡出。"
L["Move Questie's nameplate icons"] = "移動 Questie 的名條圖示"
L["Moves Questie's quest icons beside the name, where Cinematic's quest mark goes."] = "將 Questie 的任務圖示移到名字旁,也就是 Cinematic 任務標記的位置。"
L["Move EnhanceQoL's nameplate quest marks"] = "移動 EnhanceQoL 的名條任務標記"
